import re
import logging

from taf.ue.plugin.viavi.Exception import SchemaInconsistent

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SchemaField(object):
    def __init__(self, name, not_null=False, optional=False, checks=None):
        """
        Single field of Schema ORM, based on this type the SchemaObject is transfering data to and from the object.

        :param str name: String name of the field in Schema
        :param bool not_null: If set to True, value of this parameter cannot be None or empty string.
        :param bool optional: If set to True, parameter does not have to be present in
                                the schema dict or in schema parameters, it will have default constructor value.
        """
        self.name = name
        self.not_null = not_null
        self.optional = optional
        self.checks = checks


class SchemaObject(object):
    def __init__(self):
        """
        Simple ORM to convert data structures from APIs into Object and to serialize Objects.
        This is used to check the minimal contract, and to control data presentation.
        """
        self.__check_not_null()

    def __check_not_null(self):
        for attribute_name, attribute_field in self.__get_schema_class_attributes():
            if attribute_field.not_null is True:
                attribute_value = getattr(self, attribute_name)
                if attribute_field.checks:
                    for check in attribute_field.checks:
                        check(attribute_name, attribute_value)
                if attribute_value is None or attribute_value == "":
                    error_msg = "{class_name} object attribute {attribute_name} is not allowed to be empty, but its provided value is empty."
                    raise SchemaInconsistent(error_msg.format(
                        class_name=self.__class__.__name__,
                        attribute_name=attribute_name,
                    ))

    @classmethod
    def __get_schema_class_attributes(cls):
        for attribute_name in dir(cls):
            attribute_field = getattr(cls, attribute_name)

            if not isinstance(attribute_field, SchemaField):
                continue
            yield attribute_name, attribute_field

    @classmethod
    def from_object_dict(cls, data):
        """
        Load data from dictionary structure into the object.

        :param dict data: Data of given schema
        :return SchemaObject: Returns instance of subclass of SchemaObject.
        """
        try:
            object_attributes = dict()

            for attribute_name, attribute_field in cls.__get_schema_class_attributes():
                if attribute_field.optional is False or attribute_field.name in data:
                    if attribute_field.checks:
                        for check in attribute_field.checks:
                            check(attribute_name, data[attribute_field.name])
                    object_attributes[attribute_name] = data[attribute_field.name]
        except KeyError as e:
            error_msg = "Schema data is inconsistent or faulty. Error on {}"
            raise SchemaInconsistent(error_msg.format(e))

        return cls(**object_attributes)

    def to_dict(self):
        """
        Serialize to dictionary structure.

        :return dict: Object as dict, with schema data parameters.
        """
        dict_data = dict()

        try:
            for attribute_name in dir(self):
                attribute_value = getattr(self, attribute_name)

                object_type = type(self)
                model_field = getattr(object_type, attribute_name)
                if not isinstance(model_field, SchemaField) or attribute_name.startswith("_"):
                    continue
                parameter_name = model_field.name

                dict_data[parameter_name] = attribute_value

        except AttributeError as e:
            error_msg = "Schema attributes that is being serialized is not consistent. Error on {}"
            raise SchemaInconsistent(error_msg.format(e))

        return dict_data

    @staticmethod
    def is_valid_ip(attribute_name, attribute_value):
        regex = r'''^(25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(
                    25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(
                    25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)\.(
                    25[0-5]|2[0-4][0-9]|[0-1]?[0-9][0-9]?)'''
        if not re.search(regex, attribute_value):
            error_msg = "Schema value {attribute_value} for attribute {attribute_name} is not consistent".format(
                attribute_value=attribute_value, attribute_name=attribute_name)
            raise SchemaInconsistent(error_msg)

    @staticmethod
    def check_server_type(attribute_name, attribute_value):
        if attribute_value.lower() != "windows" and attribute_value.lower() != "linux" and attribute_value.lower() != "":
            msg = ("Specify valid pppd_server_type property under data transfer in the configuration file."
                   " Currently supported values are Linux and Windows")
            logger.debug(msg)
            raise SchemaInconsistent(msg)

    @staticmethod
    def is_boolean(attribute_name, attribute_value):
        if not isinstance(attribute_value, bool):
            msg = ("{attribute_name} = {attribute_value} should be boolean".format(attribute_value=attribute_value,
                                                                                   attribute_name=attribute_name))
            raise SchemaInconsistent(msg)

    @staticmethod
    def check_interface_mode(attribute_name, attribute_value):
        if attribute_value.lower() != 'combined' and attribute_value.lower() != 'dedicated':
            msg = (
                "{attribute_name} = {attribute_value} is not consistent . Supported values are Combined, Dedicated".format(
                    attribute_value=attribute_value,
                    attribute_name=attribute_name))
            raise SchemaInconsistent(msg)

    @staticmethod
    def check_frequency_range(attribute_name, attribute_value):

        if int(attribute_value) != 1 and int(attribute_value) != 2:
            msg = (
                "{attribute_name} = {attribute_value} is not consistent . Supported values are 1, 2".format(
                    attribute_value=attribute_value,
                    attribute_name=attribute_name))
            raise SchemaInconsistent(msg)

    @staticmethod
    def check_subcarrier_spacing(attribute_name, attribute_value):

        if int(attribute_value) != 0 and int(attribute_value) != 1 and int(attribute_value) != 2:
            msg = (
                "{attribute_name} = {attribute_value} is not consistent . Supported values are 0, 1, 2".format(
                    attribute_value=attribute_value,
                    attribute_name=attribute_name))
            raise SchemaInconsistent(msg)

    @staticmethod
    def check_mode(attribute_name, attribute_value):
        if attribute_value != 'NAS_MODE':
            msg = (
                "{attribute_name} = {attribute_value} is not consistent . Supported value is NAS mode".format(
                    attribute_value=attribute_value,
                    attribute_name=attribute_name))
            raise SchemaInconsistent(msg)
